
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_pearson_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_pearson", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.392366369172902e+01, 9.026877792597539e+01, 8.527118342030906e+01, 7.858685053858240e+01, 6.992428823453069e+01, 5.919090211814930e+01, 4.670588783242877e+01, 3.338483732866229e+01, 2.062283332471626e+01, 1.010978199352670e+01, 4.328096903596236e+00, 2.488375205782805e+00, 1.906622456562861e+00, 1.261057455942325e+00, 6.138096247055435e-01, 1.900598670890236e-01, 3.790168489750993e-02, 4.202918129484223e-03, 1.914250899183081e-04, 2.399672222554842e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


